import { t } from "../../../../utils/I18n";
import { BuildingAmountListeners } from "../../../buildings/Buildings";
import { Flag } from "../../../Flag";
import { hasFlag, setFlag } from "../../../Flags";
import { registerPostRetirementListener } from "../../../Retire";
import { Storyline } from "../../../storylines/Storyline";
import { Storylines } from "../../../storylines/Storylines";
import { buildEvent } from "../../EventMessageBuilder";
import { triggerEvent } from "../../Events";
import { EventTag } from "../../GameEvent";

export const buildingBlocksStoryline = new Storyline(
  "buildingBlocks",
  t("Building Blocks"),
  50,
  10,
  (state) =>
    hasFlag(state, Flag.AlternateLand)
      ? hasFlag(state, Flag.FamiliarsUnlocked)
        ? t(
            "Dispose of Furniture a total of 20 times across all retirements. Tip: You are playing on Classic Mode! That means you cannot dispose of Furniture easily. But getting rid of a Familiar counts as disposing of a Familiar Crate!",
          )
        : t(
            "Dispose of Furniture a total of 20 times across all retirements. Tip: You are playing on Classic Mode! That means you cannot dispose of Furniture. Continue making progress in the game and check back later!",
          )
      : t("Dispose of Furniture a total of 20 times across all retirements"),
  (state) => t("Disposing of Furniture recovers their cost"),
  (state) => true,
);

export function loadBuildingBlocks() {
  Storylines.register(buildingBlocksStoryline);
  const eventBuilder = buildEvent(
    "buildingBlocks",
    t("(Storyline) Building Blocks"),
    [EventTag.STORYLINE],
  ).setStorylineIds(buildingBlocksStoryline.getId());

  eventBuilder.message(
    t(`*Ugh.* You frown once more as you inevitably get rid of that last piece of furniture. Your home is so small - there isn't enough room! How many times have you had to do this?
    
What makes you extra disappointed is the fact that you put in a lot of work and *materials* into that...`),
  );
  eventBuilder
    .message(
      t(`Suddenly, you have an idea. Right now you are just *getting rid* of your furniture in order to make space. But what if instead you could simply... *take it apart*?
      
Wait. You give it a little more thought...`),
    )
    .option(
      t("Continue"),
      {
        transform: (state) => {
          state = buildingBlocksStoryline.complete(state);
          state = buildingBlocksStoryline.activateBonus(state);
          state = setFlag(Flag.DemolishRecoversCostUnlocked)(state);
          return state;
        },
      },
      "end",
    );
  eventBuilder
    .message(
      t(`You realize it should actually be *really easy*! You think of the procedure and how it would work... Yes, you should be able to *recover your costs*!
      
Hastily, you write down your idea for posterity. But you're planning to put it into practice the very next time you need more room!

**You have completed the "Building Blocks" Storyline! From now on, you will recover the resources you spent on Furniture when you dispose of it. This will persist even after retirement!**

*Note: The resources obtained this way will let you go above your storage caps, but you will only be able to spend up to your cap at one time.*`),
    )
    .tag("end");

  const event = eventBuilder.build();

  BuildingAmountListeners.register((state, building) => {
    if (
      !event.hasTriggered(state) &&
      !buildingBlocksStoryline.isCompleted(state) &&
      (state.world.variables["demolishCount"] ?? 0) >= 20
    ) {
      state = triggerEvent(event)(state);
    }
    return state;
  }, event.getId());

  registerPostRetirementListener(
    buildingBlocksStoryline.getId(),
    (state, isMock) => {
      if (buildingBlocksStoryline.isBonusActive(state)) {
        state = setFlag(Flag.DemolishRecoversCostUnlocked)(state);
      }
      return state;
    },
  );
}
