import React, {
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import { StyleSheet, View } from "react-native";
import { getBestiaryVisibleEnemies } from "../../backend/exploration/enemies/Enemy";
import { GameState } from "../../backend/GameState";
import {
  addGameStateListener,
  clearGameStateListener,
} from "../../backend/GameStateListeners";
import { getUICommands } from "../../backend/UICommands";
import { fromEntries } from "../../utils/CoreUtils";
import { BestiaryEnemyContainer } from "../utility/BestiaryEnemyContainer";
import Divider from "../utility/Divider";
import { useGameState } from "../utility/useGameState";
import { VisibilityContext } from "../utility/VisibilityContext";

function BestiaryContainer() {
  const [expandedEnemyIds, setExpandedEnemyIds] = useState({});
  const setEnemyCallback = useCallback(
    (enemyId: string, force?: boolean) => {
      const newEnemyIds = {
        ...expandedEnemyIds,
      };
      newEnemyIds[enemyId] = force ?? !expandedEnemyIds[enemyId];
      setExpandedEnemyIds(newEnemyIds);
    },
    [expandedEnemyIds],
  );

  const [topEnemyId, setTopEnemyId] = useState(null);

  const state = useGameState();
  const allEnemies = getBestiaryVisibleEnemies(state);
  const allEnemyIndices = fromEntries(
    allEnemies.map((enemy, idx) => [enemy.getId(), idx]),
  );

  const enemyString = allEnemies.map((enemy) => enemy.getId()).join(",");

  const enemyContainers = useMemo(
    () =>
      allEnemies
        .sort((a, b) => {
          if (a.getId() == topEnemyId) {
            return -1;
          }
          if (b.getId() == topEnemyId) {
            return 1;
          }
          return allEnemyIndices[a.getId()] - allEnemyIndices[b.getId()];
        })
        .map((enemy) => {
          return (
            <BestiaryEnemyContainer
              key={enemy.getId()}
              enemy={enemy}
              collapsed={!expandedEnemyIds[enemy.getId()]}
              onPressExpand={setEnemyCallback.bind(null, enemy.getId(), null)}
            />
          );
        }),
    [enemyString, expandedEnemyIds, setEnemyCallback, topEnemyId],
  );

  const visible = useContext(VisibilityContext);
  useEffect(() => {
    if (!visible) {
      setTopEnemyId(null);
    }
  }, [visible]);

  const processUICommand = useCallback(
    (uiCommand: string) => {
      if (uiCommand.startsWith("goToEnemy:")) {
        const enemyId = uiCommand.split(":")[1];
        setTopEnemyId(enemyId);
        setEnemyCallback(enemyId, true);
      }
    },
    [setEnemyCallback, setTopEnemyId],
  );

  const processUICommands = useCallback(
    (state: GameState) => {
      const uiCommands = getUICommands(state);
      uiCommands.forEach(processUICommand);
      state.run.uiCommands = uiCommands.filter(
        (uiCommand) => !uiCommand.startsWith("goToEnemy:"),
      );
      return state;
    },
    [processUICommand],
  );

  useEffect(() => {
    if (visible) {
      addGameStateListener("bestiaryUiCommand", (newState) => {
        const uiCommands = getUICommands(newState);
        if (
          uiCommands.filter((command) => command.startsWith("goToEnemy:"))
            .length > 0
        ) {
          return (state) => processUICommands(state);
        }
      });
      return () => clearGameStateListener("bestiaryUiCommand");
    }
  }, [processUICommands, visible]);

  return useMemo(() => {
    if (allEnemies.length === 0) {
      return null;
    }
    return (
      <View>
        {enemyContainers.map((enemyContainer, idx) => {
          return (
            <View key={allEnemies[idx].getId()}>
              <Divider />
              {enemyContainer}
            </View>
          );
        })}
        <Divider />
      </View>
    );
  }, [enemyString, enemyContainers]);
}

export default function Bestiary() {
  return (
    <View style={styles.bestiaryContainer}>
      <BestiaryContainer />
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "stretch",
    justifyContent: "flex-start",
    width: "100%",
  },
  headerContainer: {
    marginBottom: 16,
  },
  valueText: {
    minWidth: 60,
    textAlign: "right",
    marginLeft: 8,
  },
  valueTextLong: {
    minWidth: 112,
  },
  bestiaryContainer: {
    marginTop: 16,
  },
  captionText: {
    flex: 1,
  },
});
