import { Ionicons } from "@expo/vector-icons";
import React, { useCallback, useMemo, useRef } from "react";
import { StyleSheet, View } from "react-native";
import { Switch, useTheme } from "react-native-paper";
import { isAutocastUnlocked } from "../../backend/autocast/Autocast";
import {
  isItemBeingAutosold,
  toggleItemAutosold,
} from "../../backend/autocast/Market";
import { isMarketUnlocked } from "../../backend/buildings/SaleStall";
import { getConcatenatedRequirements } from "../../backend/events/progression/LevelUp";
import { getEquippedItems } from "../../backend/items/Equipment";
import {
  EquippableItem,
  getEquippedAmountOfItem,
} from "../../backend/items/equipment/EquippableItem";
import { getTotalAmountOfItem } from "../../backend/items/Inventory";
import { getMaxItemQuality } from "../../backend/items/Item";
import {
  calculateAboveLevels,
  calculateOddsByQuality,
} from "../../backend/items/ItemQualityUtils";
import { isItemQualityUnlocked } from "../../backend/items/Items";
import { TransmutationSpell } from "../../backend/items/transmute/TransmutationSpell";
import { SpellElement, translateElement } from "../../backend/spells/Elements";
import { Storylines } from "../../backend/storylines/Storylines";
import { keysOf } from "../../utils/CoreUtils";
import { formatNumber } from "../../utils/FormattingUtils";
import { t } from "../../utils/I18n";
import { Button } from "../utility/Button";
import { CostViewer } from "../utility/CostViewer";
import { Markdown } from "../utility/Markdown";
import { SpellWizardsInfo } from "../utility/SpellWizardsInfo";
import Styles from "../utility/Styles";
import { Text } from "../utility/Text";
import { useGameState } from "../utility/useGameState";
import { ItemInfo } from "./ItemInfo";

export interface TransmuteSpellDetailsProps {
  spell: TransmutationSpell;
}

export function TransmuteSpellInfo(props: TransmuteSpellDetailsProps) {
  const state = useGameState();

  const spell = props.spell;
  const item = spell.getItem();
  const params = item.getDefaultParams();
  const totalOwnedText = t(`Total owned: {{amount}}`, {
    amount: getTotalAmountOfItem(item, state),
  });
  const cost = spell.getCraftingMaterials(state);
  const isCraftable = spell.isVisible(state);

  const theme = useTheme();

  const concatenatedRequirements = getConcatenatedRequirements(spell);
  const cannotCastText = t(
    `You do not meet the requirements to cast this Transmutation spell. You need: {{requirements}}`,
    { requirements: concatenatedRequirements },
  );

  const exp = spell.getMainExp(state);

  const expGainText =
    exp.element != null
      ? t("Exp gain: +{{amount}} {{element}} exp", {
          amount: formatNumber(exp.expMax),
          element: translateElement(exp.element),
        })
      : t("Exp gain: +{{min}}~{{max}} exp (various)", {
          min: formatNumber(exp.expMin),
          max: formatNumber(exp.expMax),
        });

  const itemStack = useMemo(
    () => ({
      itemOccurrence: { itemId: item.getId(), params },
      amount: 1,
    }),
    [item.getId()],
  );

  return useMemo(
    () => (
      <View>
        <ItemInfo itemStack={itemStack} showTile={false} />
        <Markdown>{totalOwnedText}</Markdown>
        <Markdown>{expGainText}</Markdown>
        <View style={styles.costContainer}>
          <View style={styles.costTextContainer}>
            <Markdown>{t("Cost:")}</Markdown>
          </View>
          <CostViewer resources={cost.resources} items={cost.items} />
        </View>
        {!isCraftable && (
          <View style={styles.actionRow}>
            <Text
              style={[styles.cannotCraftText, { color: theme.colors.error }]}
            >
              {cannotCastText}
            </Text>
          </View>
        )}
      </View>
    ),
    [
      itemStack,
      totalOwnedText,
      expGainText,
      JSON.stringify(cost),
      isCraftable,
      cannotCastText,
      theme,
    ],
  );
}

export function TransmuteSpellDetails(props: TransmuteSpellDetailsProps) {
  const state = useGameState();
  const stateRef = useRef(state);
  stateRef.current = state;

  const spell = props.spell;
  const item = spell.getItem();
  const params = item.getDefaultParams();
  const equippedAmount = getEquippedAmountOfItem(item, state);
  let itemQualityText = "";
  if (item.isItemQualityValid() && isItemQualityUnlocked(state)) {
    const itemStacksInInventory = state.run.inventory.filter(
      (itemStack) => itemStack.itemOccurrence.itemId == item.getId(),
    );
    let itemQualities = {};
    for (let itemStack of itemStacksInInventory) {
      itemQualities[itemStack.itemOccurrence.params?.itemQuality ?? 0] =
        itemStack.amount;
    }
    if (item instanceof EquippableItem) {
      for (let equippedItem of getEquippedItems(state, item.getSlot())) {
        if (equippedItem?.itemId == item.getId()) {
          const quality = equippedItem.params?.itemQuality ?? 0;
          itemQualities[quality] = (itemQualities[quality] ?? 0) + 1;
        }
      }
    }
    // @ts-ignore This is known correct
    const sortedQualities: [string, number][] = Object.entries(
      itemQualities,
    ).sort((a, b) => Number.parseInt(b[0]) - Number.parseInt(a[0]));
    if (sortedQualities.length > 0) {
      itemQualityText = t("Highest quality owned: {{qualitiesList}}", {
        qualitiesList: sortedQualities
          .slice(0, 3)
          .map((entry) =>
            entry[0] == "0"
              ? t("Base x{{amount}}", { amount: formatNumber(entry[1]) })
              : t("+{{quality}} x{{amount}}", {
                  quality: formatNumber(Number.parseInt(entry[0])),
                  amount: formatNumber(entry[1]),
                }),
          )
          .join(t(", ")),
      });
    }
  }
  const totalOwnedText =
    equippedAmount > 0
      ? t("Total owned: {{amount}} (+{{equipped}} equipped)", {
          amount: getTotalAmountOfItem(item, state),
          equipped: formatNumber(equippedAmount),
        })
      : t(`Total owned: {{amount}}`, {
          amount: getTotalAmountOfItem(item, state),
        });

  const cost = spell.getCraftingMaterials(state);
  const canTransmute = spell.canCraft(state);
  const isCraftable = spell.isVisible(state);
  const theme = useTheme();

  const concatenatedRequirements = getConcatenatedRequirements(spell);
  const cannotCastText = t(
    `You do not meet the requirements to cast this Transmutation spell. You need: {{requirements}}`,
    { requirements: concatenatedRequirements },
  );

  const exp = state.options.showSpellExp
    ? spell.getMainExp(state)
    : { element: SpellElement.Fire, expMax: 0, expMin: 0 };

  const expGainText = state.options.showSpellExp
    ? exp.element != null
      ? t("Exp gain: +{{amount}} {{element}} exp", {
          amount: formatNumber(exp.expMax),
          element: translateElement(exp.element),
        })
      : t("Exp gain: +{{min}}~{{max}} exp (various)", {
          min: formatNumber(exp.expMin),
          max: formatNumber(exp.expMax),
        })
    : "";

  const maxCraftAmount = spell.timesCraftable(state);

  const transmuteCallback = useCallback(() => {
    stateRef.current.apply(spell.doAction.bind(spell, {}));
  }, [item]);

  const transmuteMaxCallback = useCallback(() => {
    stateRef.current.apply(spell.craftMax.bind(spell));
  }, [item]);

  const transmuteIntermediateCallback = useCallback(() => {
    stateRef.current.apply(
      (state) => spell.craftWithIntermediate(state, 1).state,
    );
  }, [item]);

  const transmuteMaxVisible = maxCraftAmount > 1;

  const transmuteIntermediateVisible =
    spell.isCraftIntermediatePotentiallyPossible(state);
  const transmuteIntermediateEnabled = spell.isCraftIntermediatePossible(state);

  const itemStack = useMemo(
    () => ({
      itemOccurrence: { itemId: item.getId(), params },
      amount: 1,
    }),
    [item.getId()],
  );

  const salePrice = item.getSalePrice(state, params);
  const salePriceText = t("Sale price: {{salePrice}}:coins:", {
    salePrice: formatNumber(salePrice),
  });

  const isFavorite = state.global.favoriteTransmutationSpells.includes(
    spell.getId(),
  );
  const toggleFavorite = useCallback(() => {
    stateRef.current.apply((state) => {
      const favorite = state.global.favoriteTransmutationSpells.includes(
        spell.getId(),
      );
      if (favorite) {
        state.global.favoriteTransmutationSpells =
          state.global.favoriteTransmutationSpells.filter(
            (spellId) => spellId != spell.getId(),
          );
      } else {
        state.global.favoriteTransmutationSpells.push(spell.getId());
      }
      return state;
    });
  }, [spell]);

  const favoriteComponent = useMemo(
    () => (
      <Ionicons
        accessibilityLabel={
          isFavorite ? t("Remove from Favorites") : t("Add to Favorites")
        }
        onPress={toggleFavorite}
        name={isFavorite ? "heart" : "heart-outline"}
        color={theme.colors.onBackground}
        size={32}
        style={styles.favoriteComponent}
      />
    ),
    [isFavorite, toggleFavorite, theme],
  );

  const onAutosoldPress = useCallback(() => {
    stateRef.current.apply((s) =>
      toggleItemAutosold(s, {
        itemId: item.getId(),
        params: item.getDefaultParams(),
      }),
    );
  }, [item]);

  const isBeingAutosold = isItemBeingAutosold(state, {
    itemId: item.getId(),
    params: item.getDefaultParams(),
  });

  const marketToggle = useMemo(
    () =>
      isMarketUnlocked(state) &&
      !item.isItemQualityValid() && (
        <View style={[Styles.mt4, Styles.flexRowAlignCenter, Styles.flex]}>
          <Text>{t("Sell automatically through Market Stalls")}</Text>
          <Switch
            style={Styles.ml8}
            value={isBeingAutosold}
            onValueChange={onAutosoldPress}
          />
        </View>
      ),
    [onAutosoldPress, isBeingAutosold, isMarketUnlocked(state), item],
  );

  const itemQualityOnTransmuteUnlocked = Storylines.getByIdNullable(
    "transmutationPrayer1",
  )?.isBonusActive?.(state);
  let aboveLevels = 0;
  if (item.isItemQualityValid() && itemQualityOnTransmuteUnlocked) {
    aboveLevels = calculateAboveLevels(state, spell);
  }

  const maxQuality = getMaxItemQuality(state);

  const itemQualityOddsComponent = useMemo(() => {
    if (!itemQualityOnTransmuteUnlocked || !item.isItemQualityValid()) {
      return null;
    }
    const odds = calculateOddsByQuality(state, aboveLevels);
    const oddsEntries = Object.entries(odds);
    const oddsText = oddsEntries
      .map((oddsPair, idx) => {
        const chance = formatNumber(oddsPair[1] * 100, { showDecimals: true });
        if (
          idx == oddsEntries.length - 1 &&
          Number.parseInt(oddsPair[0]) != maxQuality
        ) {
          return t("+{{quality}} and higher: {{chance}}%", {
            quality: oddsPair[0],
            chance,
          });
        }
        if (Number.parseInt(oddsPair[0]) == 0) {
          return t("Base: {{chance}}%", { chance });
        }
        return t("+{{quality}}: {{chance}}%", {
          quality: oddsPair[0],
          chance,
        });
      })
      .join(t(", "));

    const elementIconsText = keysOf(spell.getCraftingElementLevelRequirements())
      .map((element) => `:${element.toLowerCase()}:`)
      .join("");

    return (
      <Markdown>
        {t(
          "Levels for item quality: {{levels}} ({{elementIcons}}) - ^Odds by quality^<{{oddsText}}>",
          {
            levels: formatNumber(aboveLevels),
            oddsText,
            elementIcons: elementIconsText,
          },
        )}
      </Markdown>
    );
  }, [
    item.isItemQualityValid(),
    itemQualityOnTransmuteUnlocked,
    aboveLevels,
    maxQuality,
    spell,
  ]);

  return useMemo(
    () => (
      <View style={styles.craftingDetailsContainer}>
        <ItemInfo
          itemStack={itemStack}
          belowTileComponent={favoriteComponent}
          showTile={true}
        />
        <Markdown>{totalOwnedText}</Markdown>
        {itemQualityText != "" && <Markdown>{itemQualityText}</Markdown>}
        {itemQualityOddsComponent}
        {expGainText != "" && <Markdown>{expGainText}</Markdown>}
        <View style={styles.costContainer}>
          <Markdown>{t("Cost:")}</Markdown>
          <CostViewer resources={cost.resources} items={cost.items} />
        </View>
        <View style={Styles.mt4}>
          <Markdown>{salePriceText}</Markdown>
        </View>
        {marketToggle}
        {isAutocastUnlocked(state) && (
          <View style={Styles.mt4}>
            <SpellWizardsInfo spellId={spell.getId()} />
          </View>
        )}
        <View style={styles.actionRow}>
          {isCraftable ? (
            [
              <Button
                key="craft_button"
                enableAutoRepress={true}
                autoRepressConfig={{
                  dropoffMultiplier: 0.8,
                  startingThreshold: 300,
                  startingRepressTime: 200,
                  minTimeMs: 50,
                }}
                disabled={!canTransmute}
                onPress={transmuteCallback}
              >
                {t("Transmute")}
              </Button>,
              transmuteMaxVisible && (
                <Button
                  key="craft_max"
                  disabled={!canTransmute}
                  onPress={transmuteMaxCallback}
                >
                  {t("Transmute All ({{amount}})", {
                    amount: formatNumber(maxCraftAmount),
                  })}
                </Button>
              ),
              transmuteIntermediateVisible && (
                <Button
                  key="craft_intermediate"
                  onPress={transmuteIntermediateCallback}
                  disabled={!transmuteIntermediateEnabled}
                  disableDisabledRenderingOptimization={true}
                  enableAutoRepress={true}
                >
                  {t("Transmute Materials and Item", {
                    amount: formatNumber(maxCraftAmount),
                  })}
                </Button>
              ),
            ]
          ) : (
            <Text
              style={[styles.cannotCraftText, { color: theme.colors.error }]}
            >
              {cannotCastText}
            </Text>
          )}
        </View>
      </View>
    ),
    [
      itemStack,
      totalOwnedText,
      expGainText,
      JSON.stringify(cost.resources),
      JSON.stringify(cost.items),
      isAutocastUnlocked(state),
      canTransmute,
      transmuteMaxVisible,
      transmuteMaxCallback,
      maxCraftAmount,
      stateRef,
      theme,
      isCraftable,
      favoriteComponent,
      transmuteIntermediateCallback,
      transmuteIntermediateEnabled,
      transmuteIntermediateVisible,
      salePriceText,
      marketToggle,
      itemQualityOddsComponent,
    ],
  );
}

const styles = StyleSheet.create({
  craftingDetailsContainer: {
    marginBottom: 16,
  },
  tagRow: {
    marginVertical: 4,
  },
  actionRow: {
    flexDirection: "row",
    flexWrap: "wrap",
    marginTop: 8,
    gap: 8,
  },
  actionButtonContainer: {
    marginRight: 8,
  },
  costContainer: {
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "flex-start",
    marginTop: 4,
  },
  costTextContainer: {
    marginRight: 8,
  },
  inventoryFullContainer: {
    flex: 1,
    marginHorizontal: 8,
  },
  cannotCraftText: {
    fontStyle: "italic",
  },
  favoriteComponent: {
    position: "absolute",
    left: -16,
    top: -4,
  },
});
