import { t } from "../../../../utils/I18n";
import { GameState } from "../../../GameState";
import { registerPostRetirementListener } from "../../../Retire";
import {
  clearCalculatedIncomeCache,
  IncomeOverTimeProducer,
  IncomeOverTimeProducers,
} from "../../../timetick/IncomeOverTime";
import { EquipmentChangeListeners, EquipmentSlot } from "../../Equipment";
import { addToInventory } from "../../Inventory";
import { ItemParams } from "../../Item";
import { EquippableItem } from "../EquippableItem";

class Mimic extends EquippableItem {
  getId(): string {
    return "mimic";
  }
  getSlot(): EquipmentSlot {
    return EquipmentSlot.Accessory;
  }
  getPicture() {
    return require("./mimic.png");
  }
  getBaseName(params: ItemParams): string {
    return t("Mimic");
  }
  getDescription(state: GameState, params: ItemParams): string | undefined {
    return t("Once defeated, now willing to cooperate...");
  }
  getEffectExtra(state: GameState, params: ItemParams): string {
    return t("While equipped, obtain 100:coins:/sec");
  }
  getBaseSalePrice(state: GameState, params: ItemParams): number {
    return 1;
  }
  isItemQualityValid(): boolean {
    return false;
  }
}

export const mimic = new Mimic();

IncomeOverTimeProducers.register(
  new IncomeOverTimeProducer(mimic.getId(), mimic.getDefaultName(), (state) => {
    if (mimic.isEquippedWithAnyParams(state)) {
      return { Coins: 100 };
    }
    return {};
  }),
);

EquipmentChangeListeners.register(
  (state) => clearCalculatedIncomeCache(state),
  "mimic",
);

registerPostRetirementListener(mimic.getId(), (state) => {
  if (state.global.mr1flags.mimic && state.options.enableMr1Rewards) {
    state = addToInventory({ itemId: mimic.getId(), params: {} }, 1, state);
  }
  return state;
});
