import React, { useCallback, useContext, useEffect, useMemo } from "react";
import { StyleSheet, View } from "react-native";
import { SegmentedButtons } from "react-native-paper";
import { GameState } from "../backend/GameState";
import {
  addGameStateListener,
  clearGameStateListener,
} from "../backend/GameStateListeners";
import { getUICommands } from "../backend/UICommands";
import { t } from "../utils/I18n";
import Bestiary from "./compendium/Bestiary";
import ItemCompendium from "./compendium/ItemCompendium";
import { GameStateFreezer } from "./utility/GameStateFreezer";
import Styles from "./utility/Styles";
import { Text } from "./utility/Text";
import { UIContext, useUIStateFromContext } from "./utility/UIContext";
import { VisibilityContext } from "./utility/VisibilityContext";

export default function Compendium() {
  const uiContext = useContext(UIContext);
  const [selectedTab, setSelectedTab] = useUIStateFromContext(
    uiContext,
    "compendiumTab",
    "item",
  );
  const buttons = useMemo(
    () => [
      { value: "item", label: t("Items") },
      { value: "bestiary", label: t("Bestiary") },
    ],
    [],
  );
  const buttonSelectors = (
    <SegmentedButtons
      value={selectedTab}
      onValueChange={setSelectedTab}
      buttons={buttons}
    />
  );

  const processUICommand = useCallback(
    (uiCommand: string) => {
      if (uiCommand == "goToBestiary") {
        setSelectedTab("bestiary");
      } else if (uiCommand == "goToItemCompendium") {
        setSelectedTab("item");
      }
    },
    [setSelectedTab],
  );

  const processUICommands = useCallback(
    (state: GameState) => {
      const uiCommands = getUICommands(state);
      uiCommands.forEach(processUICommand);
      state.run.uiCommands = uiCommands.filter(
        (uiCommand) =>
          uiCommand != "goToBestiary" && uiCommand != "goToItemCompendium",
      );
      return state;
    },
    [processUICommand],
  );

  const visible = useContext(VisibilityContext);

  useEffect(() => {
    if (visible) {
      addGameStateListener("compendiumUiCommand", (newState) => {
        const uiCommands = getUICommands(newState);
        if (
          uiCommands.filter(
            (command) =>
              command == "goToBestiary" || command == "goToItemCompendium",
          ).length > 0
        ) {
          return (state) => processUICommands(state);
        }
      });
      return () => clearGameStateListener("compendiumUiCommand");
    }
  }, [processUICommands, visible]);

  return (
    <View>
      <View style={styles.headerContainer}>
        <Text h1>{t("Compendium")}</Text>
      </View>

      {buttonSelectors}

      <View style={Styles.mt16}>
        <View style={selectedTab != "item" && { display: "none" }}>
          <GameStateFreezer isVisible={selectedTab == "item"}>
            <ItemCompendium />
          </GameStateFreezer>
        </View>
        <View style={selectedTab != "bestiary" && { display: "none" }}>
          <GameStateFreezer isVisible={selectedTab == "bestiary"}>
            <Bestiary />
          </GameStateFreezer>
        </View>
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    alignItems: "stretch",
    justifyContent: "flex-start",
    width: "100%",
  },
  headerContainer: {
    marginBottom: 16,
  },
  captionText: {
    flex: 1,
  },
});
