import { keysOf } from "../../../../utils/CoreUtils";
import { formatNumber } from "../../../../utils/FormattingUtils";
import { t } from "../../../../utils/I18n";
import { Flag } from "../../../Flag";
import { getCombatVariable, hasFlag, setCombatVariable } from "../../../Flags";
import { GameState } from "../../../GameState";
import { TemporaryEffect } from "../../../temporaryeffects/TemporaryEffect";
import {
  grantTemporaryEffect,
  TemporaryEffectData,
  TemporaryEffects,
} from "../../../temporaryeffects/TemporaryEffects";
import { getSecondsPlayed } from "../../../timetick/TotalTimePlayed";
import { AttackTarget } from "../../AttackTarget";
import { clearDamageTally, pushToMessageLog } from "../../Exploration";
import {
  BattlerAction,
  BattlerStats,
  BestiaryState,
  Enemy,
  EnemyLoot,
} from "../Enemy";

class MeasureDamageTemporaryEffect extends TemporaryEffect {
  getId(): string {
    return "measureDamage";
  }
  getDisplayName(): string {
    return t("Measure Damage");
  }
  isDispellable(): boolean {
    return false;
  }
  getDisplayDescription(
    state: GameState,
    temporaryEffectData: TemporaryEffectData,
  ): string {
    return t("Measures damage received");
  }
}

export const measureDamage = new MeasureDamageTemporaryEffect();
TemporaryEffects.register(measureDamage);

class KnightInShiningArmorDummy extends Enemy {
  getId(): string {
    return "knightInShiningArmorDummy";
  }

  getName(): string {
    return t("Knight in Shining Armor");
  }

  getBaseStats(): BattlerStats {
    return {
      maxHP: 1e99,
      attack: 0,
      defense: 0,
      attackDelay: 30.0,
      accuracy: 100,
      dodge: 100,
      crit: 0,
    };
  }

  getPicture(state: GameState) {
    return require("./knightInShiningArmor.png");
  }

  getLevel(): number {
    return 80;
  }

  getCoinsAwardedBase(state: GameState): number {
    return 0;
  }

  getMonstiumAwardedBase(state: GameState): number {
    return 0;
  }

  getBestiaryState(state: GameState): BestiaryState {
    if (!hasFlag(state, Flag.TrainingDummyUnlocked)) {
      return BestiaryState.Hidden;
    }
    return BestiaryState.Loot;
  }

  onEncounter(state: GameState): GameState {
    state = grantTemporaryEffect(measureDamage.getId(), Infinity, {
      target: AttackTarget.Enemy,
      source: AttackTarget.Enemy,
    })(state);
    return state;
  }

  getNextAction(state: GameState): BattlerAction {
    state = setCombatVariable(
      "measuringSecondsPlayed",
      getSecondsPlayed(state),
    )(state);
    return {
      name: t("Measuring damage..."),
      delay: this.getAttackDelay(state),
      transform: (state) => {
        const secondsPlayed = getSecondsPlayed(state);
        const prevSecondsPlayed =
          getCombatVariable(state, "measuringSecondsPlayed") ??
          secondsPlayed - 1;
        const secs = secondsPlayed - prevSecondsPlayed;

        const damageTally = state.run.exploration.enemyDamageTallyByCause;
        const causes = keysOf(damageTally).sort(
          (a, b) => damageTally[b] - damageTally[a],
        );
        const damageStrings = [];
        let totalDamage = causes.reduce(
          (prev, current) => prev + damageTally[current],
          0,
        );
        for (let cause of causes.slice(0, 5)) {
          const damage = damageTally[cause];
          const damagePerSec = damage / secs;
          damageStrings.push(
            t("{{cause}}: {{damage}}:hp:/sec ({{percent}}%)", {
              cause,
              damage: formatNumber(damagePerSec),
              percent: formatNumber((damage * 100.0) / totalDamage, {
                showDecimals: true,
              }),
            }),
          );
        }

        state = pushToMessageLog(
          state,
          t(
            "You have dealt {{damage}}:hp: of damage in {{seconds}} seconds, for a total of {{dps}}:hp:/sec! Top causes: {{causeString}}",
            {
              damage: formatNumber(totalDamage),
              dps: formatNumber(totalDamage / secs, { showDecimals: true }),
              seconds: formatNumber(secs, { showDecimals: true }),
              causeString: damageStrings.join(t(", ")),
            },
          ),
        );

        state = clearDamageTally(state);

        return state;
      },
    };
  }

  isBoss(): boolean {
    return true;
  }

  getItemsAwardedBase(state: GameState): EnemyLoot[] {
    return [];
  }

  getTips(): string {
    return t(
      "He is letting us just attack him to test our damage! Maybe the information he can tell us can help us strategize...",
    );
  }
}

export const knightInShiningArmorDummy = new KnightInShiningArmorDummy();
