import { valuesOfCached } from "../../../../utils/CoreUtils";
import { t } from "../../../../utils/I18n";
import { LevelUpListeners } from "../../../events/progression/LevelUp";
import { GameState } from "../../../GameState";
import { registerPostRetirementListener } from "../../../Retire";
import {
  getElementLevel,
  getPrimaryElements,
  SpellElement,
} from "../../../spells/Elements";
import { clearResearcherExpCache } from "../../../study/Study";
import {
  registerTransformation,
  TransformationType,
} from "../../../transformation/Transformation";
import { TransformationTags } from "../../../transformation/TransformationTags";
import { EquipmentChangeListeners, EquipmentSlot } from "../../Equipment";
import { addToInventory } from "../../Inventory";
import { ItemParams } from "../../Item";
import { EquippableItem } from "../EquippableItem";

class TrophyReplica extends EquippableItem {
  getId(): string {
    return "trophyReplica";
  }
  getSlot(): EquipmentSlot {
    return EquipmentSlot.Accessory;
  }
  getPicture() {
    return require("./trophyReplica.png");
  }
  getBaseName(params: ItemParams): string {
    return t("Trophy Replica");
  }
  getDescription(state: GameState, params: ItemParams): string | undefined {
    return t("You won the Tournament of Magic! Or... did you, really?");
  }
  getEffectExtra(state: GameState, params: ItemParams): string {
    return t(
      "While equipped, if your Primary element is below Lv20, +100% Primary element Exp gain from Studying",
    );
  }
  getBaseSalePrice(state: GameState, params: ItemParams): number {
    return 1;
  }
  isItemQualityValid(): boolean {
    return false;
  }
}

export const trophyReplica = new TrophyReplica();

for (let element of valuesOfCached(SpellElement)) {
  registerTransformation(
    [[element, TransformationTags.ExpGain, TransformationTags.Study]],
    trophyReplica.getId() + element,
    trophyReplica.getDefaultName(),
    TransformationType.Multiplier,
    (state) => {
      if (
        trophyReplica.isEquippedWithAnyParams(state) &&
        getPrimaryElements(state).includes(element) &&
        getElementLevel(state, element) < 20
      ) {
        return 2.0;
      }
      return 1.0;
    },
  );
}

EquipmentChangeListeners.register(
  (state) => clearResearcherExpCache(state),
  "trophyReplica",
);
LevelUpListeners.register(
  (state, _element, _oldExp) => clearResearcherExpCache(state),
  "trophyReplica",
);

registerPostRetirementListener(trophyReplica.getId(), (state) => {
  if (state.global.mr1flags.tournament && state.options.enableMr1Rewards) {
    state = addToInventory(
      { itemId: trophyReplica.getId(), params: {} },
      1,
      state,
    );
  }
  return state;
});
