import memoize from "sonic-memoize";
import { keysOf } from "../../utils/CoreUtils";
import { GameState } from "../GameState";
import { getElementLevel, SpellElement } from "../spells/Elements";
import { applyTransformationsCached } from "../transformation/Transformation";
import { TransformationTags } from "../transformation/TransformationTags";
import { getMaxItemQuality } from "./Item";
import { TransmutationSpell } from "./transmute/TransmutationSpell";

const ITEM_QUALITY_LEVEL_DELTA_TAG = [TransformationTags.ItemQualityLevelDelta];

const BASE_NO_UPGRADE_CHANCE = 0.9;
const NO_UPGRADE_DECAY_PER_LEVEL = 0.8;
const MULTIPLIER_PER_ELEMENT_LEVEL = 0.97;

const spellIdMemoized = memoize((spellId) => ({ spellId }));

export function calculateAboveLevels(
  state: GameState,
  spell: TransmutationSpell,
): number {
  const elementRequirements = spell.getCraftingElementLevelRequirements();
  let amountAboveLevels = 0;
  for (let element in elementRequirements) {
    amountAboveLevels +=
      getElementLevel(state, element as SpellElement) -
      elementRequirements[element];
  }
  amountAboveLevels /= keysOf(elementRequirements).length;
  const amountAboveDelta = applyTransformationsCached(
    ITEM_QUALITY_LEVEL_DELTA_TAG,
    state,
    0,
    spellIdMemoized(spell.getId()),
  );
  amountAboveLevels += amountAboveDelta;
  return amountAboveLevels;
}

export function rollQualityLevel(state: GameState, amountAboveLevels: number) {
  let successful = true;
  let upgradeLevel = 0;
  const max = getMaxItemQuality(state);

  while (successful && upgradeLevel < max) {
    const intermediate = Math.max(
      amountAboveLevels * Math.pow(NO_UPGRADE_DECAY_PER_LEVEL, upgradeLevel),
      0,
    );
    const noUpgradeChance =
      Math.pow(MULTIPLIER_PER_ELEMENT_LEVEL, intermediate) *
      BASE_NO_UPGRADE_CHANCE;
    if (Math.random() < noUpgradeChance) {
      successful = false;
    } else {
      upgradeLevel++;
    }
  }

  return upgradeLevel;
}

export function calculateOddsByQuality(
  state: GameState,
  amountAboveLevels: number,
): Record<number, number> {
  const odds = {};
  const max = getMaxItemQuality(state);
  let remainingOdds = 1.0;
  let upgradeLevel = 0;

  while (upgradeLevel < max && remainingOdds > 0.01) {
    const intermediate = Math.max(
      amountAboveLevels * Math.pow(NO_UPGRADE_DECAY_PER_LEVEL, upgradeLevel),
      0,
    );
    const noUpgradeChance =
      Math.pow(MULTIPLIER_PER_ELEMENT_LEVEL, intermediate) *
      BASE_NO_UPGRADE_CHANCE;

    odds[upgradeLevel] = remainingOdds * noUpgradeChance;
    remainingOdds -= odds[upgradeLevel];
    upgradeLevel++;
  }

  odds[upgradeLevel] = (odds[upgradeLevel] ?? 0) + remainingOdds;

  return odds;
}
