import { keysOf } from "../../../utils/CoreUtils";
import { Action } from "../../action/Action";
import { GameState } from "../../GameState";
import { getResourceAmount, getResourceCap, Resource } from "../../Resources";
import { BasicChannelingSpellBase } from "../../spells/channeling/BasicChannelingSpellBase";
import { ELEMENT_FOR_RESOURCE } from "../../spells/channeling/ChannelingResources";
import { Spells } from "../../spells/Spells";
import { getTotalAmountOfItem } from "../Inventory";
import { Items } from "../Items";
import { getTransmutationSpellForItem } from "./TransmutationSpell";

// TODO: These two functions should be merged with the ones in TransmutationSpell

export function transmuteAndChannelMaterialsOfActionAndDo(
  state: GameState,
  action: Action,
): GameState {
  const cost = action.getCost(state);

  // First, try to transmute each of the item requirements
  let craftedAnything = false;
  do {
    craftedAnything = false;
    for (let itemId in cost.items) {
      const item = Items.getById(itemId);
      const amountNeeded = cost.items[itemId];
      const amountInInventory = getTotalAmountOfItem(item, state);
      if (amountInInventory >= amountNeeded) {
        continue;
      }
      const spell = getTransmutationSpellForItem(item);
      if (spell == null) {
        continue;
      }
      if (
        !spell.isEnabled(state) &&
        !spell.isCraftIntermediatePossible(state, amountNeeded)
      ) {
        continue;
      }
      // There is a spell that we can use, and we need the item
      const amountRequired = amountNeeded - amountInInventory;
      const amountPerCraft = spell.calculateAmountPerCraft(state, {
        isAutomatic: false,
      });
      const timesToCraft = Math.ceil(amountRequired / amountPerCraft);

      const result = spell.craftWithIntermediate(state, timesToCraft);
      state = result.state;
      if (result.timesCrafted > 0) {
        craftedAnything = true;
      }
    }
    // If we crafted anything, we need to repeat all of this, because some materials
    // might have disappeared
  } while (craftedAnything);

  // Next, channel any resources we might be missing
  let changedAnything = false;
  do {
    changedAnything = false;
    for (let resource of keysOf(cost.resources)) {
      const resourceAmount = cost.resources[resource];
      const heldAmount = getResourceAmount(state, resource);
      const cap = getResourceCap(state, resource);
      if (resourceAmount > cap) {
        continue;
      }
      const needed = resourceAmount - heldAmount;
      if (needed <= 0) {
        continue;
      }

      const element = ELEMENT_FOR_RESOURCE[resource];
      if (element == null) {
        continue;
      }
      const channelingSpell = Spells.getById(
        "channel" + element,
      ) as BasicChannelingSpellBase;

      // Need to remove the cache for the spell to avoid a potential infinite loop
      channelingSpell._cacheEnabled = null;
      if (!channelingSpell.isEnabled(state)) {
        continue;
      }

      // The spell is enabled, so... let's use it. Once.
      state = channelingSpell.doAction({ isAutomatic: false }, state);
      changedAnything = true;
    }
  } while (changedAnything);

  if (action.canAfford(state)) {
    state = action.doAction({ isAutomatic: false }, state);
  }

  return state;
}

export function isTransmuteAndChannelMaterialsOfActionEnabled(
  state: GameState,
  action: Action,
): boolean {
  const cost = action.getCost(state);
  if (action.canAfford(state)) {
    return true;
  }

  for (let itemId in cost.items) {
    const item = Items.getById(itemId);
    const amountNeeded = cost.items[itemId];
    const amountInInventory = getTotalAmountOfItem(item, state);
    if (amountInInventory >= amountNeeded) {
      continue;
    }
    const spell = getTransmutationSpellForItem(item);
    if (spell == null || !spell.isVisible(state)) {
      continue;
    }
    const amountPerCraft = spell.calculateAmountPerCraft(state, {
      isAutomatic: false,
    });
    if (
      !spell.isEnabled(state) &&
      !spell.isCraftIntermediatePossible(
        state,
        Math.ceil(amountNeeded / amountPerCraft),
      )
    ) {
      continue;
    }
    return true;
  }

  // It's possible that we can't craft any intermediate item, but maybe we can channel something we need?
  for (let resource in cost.resources) {
    const amountNeededForOne = cost.resources[resource];
    const amountHeld = getResourceAmount(state, resource as Resource);
    const cap = getResourceCap(state, resource as Resource);
    if (amountNeededForOne > cap || amountHeld >= amountNeededForOne) {
      continue;
    }

    // We are short of Resource

    const element = ELEMENT_FOR_RESOURCE[resource];
    if (element == null) {
      // Not essence
      continue;
    }

    // We are short of Essence

    const channelingSpell = Spells.getById(
      "channel" + element,
    ) as BasicChannelingSpellBase;
    if (!channelingSpell.isEnabled(state)) {
      continue;
    }

    // And the Channeling spell for that Essence is enabled
    return true;
  }

  return false;
}
