import { t } from "../../../../utils/I18n";
import { Flag } from "../../../Flag";
import { hasFlag } from "../../../Flags";
import { GameState } from "../../../GameState";
import { Enemy } from "../../enemies/Enemy";
import { knightInShiningArmorDummy } from "../../enemies/training/KnightInShiningArmorDummy";
import {
  DungeonFloor,
  encounterEnemy,
  ExplorationPossibility,
} from "../DungeonFloor";

const EXPLORATION_POSSIBILTIIES = [
  {
    weight: 100,
    transforms: encounterEnemy(knightInShiningArmorDummy),
  },
];

class TrainingCourt extends DungeonFloor {
  getId(): string {
    return "trainingCourt";
  }
  getFloorName(): string {
    return t("Training Court");
  }
  getBoss(state: GameState): Enemy {
    return knightInShiningArmorDummy;
  }
  getBreedingLevel(): number {
    return 1;
  }
  isMainStoryDungeonFloor(): boolean {
    return false;
  }
  getExplorationRequiredTimeSecBase(): number {
    return 4.0;
  }
  _getExplorationSuccessesForBossBase(): number {
    return Infinity;
  }
  getBaseExplorationPossibilities(state: GameState): ExplorationPossibility[] {
    return EXPLORATION_POSSIBILTIIES;
  }
  isUnlocked(state: GameState): boolean {
    return hasFlag(state, Flag.TrainingDummyUnlocked);
  }
}

export default new TrainingCourt();
