import { useCallback, useMemo, useRef } from "react";
import { View } from "react-native";
import { getConcatenatedRequirements } from "../../backend/events/progression/LevelUp";
import { ItemCompendiumInfo } from "../../backend/items/ItemCompendium";
import { getAllTransmutationSpellsEverCastable } from "../../backend/items/transmute/TransmutationSpell";
import { addUICommand } from "../../backend/UICommands";
import { fromEntries, keysOf } from "../../utils/CoreUtils";
import { formatNumber } from "../../utils/FormattingUtils";
import { t } from "../../utils/I18n";
import { ItemInfo } from "../inventory/ItemInfo";
import { Markdown } from "../utility/Markdown";
import { useGameState } from "../utility/useGameState";

export function ItemCompendiumDetails(props: { info: ItemCompendiumInfo }) {
  const info = props.info;
  const item = info.item;
  const params = item.getDefaultParams();
  const spell = info.transmuteSpell;

  const state = useGameState();
  const stateRef = useRef(state);
  stateRef.current = state;

  const howToObtainStrings = [];
  if (spell != null) {
    const concatenatedRequirements = getConcatenatedRequirements(spell);
    howToObtainStrings.push(
      t("Transmutation ({{requirements}})", {
        requirements: concatenatedRequirements,
      }),
    );
  }
  const goToEnemy = useCallback(
    (enemyId) =>
      stateRef.current.apply((state) => {
        addUICommand(state, "openCompendium");
        addUICommand(state, "goToBestiary");
        addUICommand(state, "goToEnemy:" + enemyId);
        return state;
      }),
    [],
  );
  const goToItem = useCallback(
    (itemId) =>
      stateRef.current.apply((state) => {
        addUICommand(state, "goToCompendiumEntry:" + itemId);
        return state;
      }),
    [],
  );
  const linkHandlers = useMemo(() => {
    return fromEntries(
      info.knownLootFromEnemies.map((lootInfo) => [
        lootInfo.enemy.getId(),
        () => goToEnemy(lootInfo.enemy.getId()),
      ]),
    );
  }, [
    info.knownLootFromEnemies.map((lootInfo) => lootInfo.enemy.getId()).join(),
  ]);
  info.knownLootFromEnemies.forEach((lootInfo) => {
    howToObtainStrings.push(
      lootInfo.lootChance != null
        ? t("[{{enemyName}}](!{{enemyId}}) ({{chance}}% to get {{amount}})", {
            enemyName: lootInfo.enemy.getName(),
            enemyId: lootInfo.enemy.getId(),
            amount: lootInfo.amount,
            chance: formatNumber(lootInfo.lootChance * 100, {
              showDecimals: true,
            }),
          })
        : t("[{{enemyName}}](!{{enemyId}}) (???)", {
            enemyName: lootInfo.enemy.getName(),
            enemyId: lootInfo.enemy.getId(),
          }),
    );
  });

  const howToObtainText = t("How to obtain: *{{howToObtain}}*", {
    howToObtain:
      howToObtainStrings.length > 0
        ? howToObtainStrings.join(t(", "))
        : t("Unknown"),
  });

  const howToObtainComponent = useMemo(
    () => (
      <View>
        <Markdown linkHandlers={linkHandlers}>{howToObtainText}</Markdown>
      </View>
    ),
    [howToObtainText, linkHandlers],
  );

  const materialsForSpells = getAllTransmutationSpellsEverCastable(
    state,
  ).filter((transmutationSpell) =>
    keysOf(transmutationSpell.getCraftingMaterialsBase(state).items).includes(
      item.getId(),
    ),
  );

  const materialsForSpellsStrings = [];
  const linkHandlersItem = useMemo(() => {
    return fromEntries(
      materialsForSpells.map((spell) => [
        spell.getItem().getId(),
        goToItem.bind(null, spell.getItem().getId()),
      ]),
    );
  }, [materialsForSpells.map((spell) => spell.getId()).join()]);

  materialsForSpells.forEach((transmutationSpell) => {
    materialsForSpellsStrings.push(
      t(":{{itemId}}:[{{itemName}}](!{{itemId}}) ({{amount}})", {
        itemId: transmutationSpell.getItem().getId(),
        itemName: transmutationSpell.getItem().getDefaultName(),
        amount: formatNumber(
          transmutationSpell.getCraftingMaterialsBase(state).items[
            item.getId()
          ],
        ),
      }),
    );
  });

  const materialsForSpellsText =
    materialsForSpellsStrings.length > 0
      ? t("Used to Transmute: *{{transmutations}}*", {
          transmutations: materialsForSpellsStrings.join(t(", ")),
        })
      : "";

  const materialsForSpellsComponent = useMemo(
    () =>
      materialsForSpellsText != "" && (
        <View>
          <Markdown linkHandlers={linkHandlersItem}>
            {materialsForSpellsText}
          </Markdown>
        </View>
      ),
    [materialsForSpellsText, linkHandlersItem],
  );

  const itemStack = useMemo(
    () => ({
      itemOccurrence: { itemId: item.getId(), params },
      amount: 1,
    }),
    [item.getId()],
  );

  const salePriceText = t("Base sale price: {{salePrice}}:coins:", {
    salePrice: formatNumber(info.salePrice),
  });

  return useMemo(
    () => (
      <View>
        <ItemInfo itemStack={itemStack} showTile={true} />
        <View>
          <Markdown>{salePriceText}</Markdown>
        </View>
        {howToObtainComponent}
        {materialsForSpellsComponent}
      </View>
    ),
    [itemStack, howToObtainComponent, materialsForSpellsComponent],
  );
}
