import { Flag } from "../Flag";
import { setFlag } from "../Flags";
import { registerPostRetirementListener } from "../Retire";
import { Storylines } from "../storylines/Storylines";
import { BuildingAmountListeners, clearLandCache } from "./Buildings";

export function loadBuildingsCommonLogic() {
  // Alternate Land
  registerPostRetirementListener("alternateLandFlag", (state, isMock) => {
    if (
      state.options.alternateLandMechanic &&
      !Storylines.getByIdNullable("blessedLand")?.isBonusActive?.(state)
    ) {
      state = setFlag(Flag.AlternateLand)(state);
    }
    return state;
  });

  BuildingAmountListeners.register((state, building) => clearLandCache(state));
}
