import { t } from "../../../utils/I18n";
import { GameEvent } from "../../events/GameEvent";
import { Flag } from "../../Flag";
import { hasFlag, hasWorldFlag, setFlag, setWorldFlag } from "../../Flags";
import { GameState } from "../../GameState";
import { DataStore } from "../../generic/DataStore";
import { registerRetirementListener } from "../../Retire";
import { getMaxOfMaxPrimaryElementLevels } from "../../spells/Elements";
import {
  registerTransformation,
  TransformationType,
} from "../../transformation/Transformation";
import { TransformationTags } from "../../transformation/TransformationTags";
import { Dungeon } from "./Dungeon";
import { DungeonFloor } from "./DungeonFloor";

const Dungeons = new DataStore<Dungeon>();
const DungeonFloors = new DataStore<DungeonFloor>();

export { Dungeons, DungeonFloors };

export function getUnlockedDungeons(state: GameState): Dungeon[] {
  return Dungeons.getAll().filter((dungeon) => dungeon.isUnlocked(state));
}

export function isDungeonFloorCompletedThisRun(
  state: GameState,
  floor: DungeonFloor | string,
): boolean {
  return hasFlag(
    state,
    (typeof floor === "string" ? floor : floor.getId()) +
      "_dungeon_floor_completed",
  );
}

export function isDungeonFloorEverCompleted(
  state: GameState,
  floor: DungeonFloor | string,
): boolean {
  return hasWorldFlag(
    state,
    (typeof floor === "string" ? floor : floor.getId()) +
      "_dungeon_floor_completed",
  );
}

export function setDungeonFloorCompleted(
  state: GameState,
  floorId: string,
): GameState {
  state = setFlag(floorId + "_dungeon_floor_completed")(state);
  state.run.lastDungeonFloorCompleted = floorId;
  return setWorldFlag(floorId + "_dungeon_floor_completed")(state);
}

export function minMPLRecommendation(state: GameState): number {
  const unlockedDungeons = getUnlockedDungeons(state);
  const floors = unlockedDungeons
    .map((dungeon) =>
      dungeon
        .getDungeonFloors()
        .filter(
          (floor) => floor.isUnlocked(state) && floor.isMainStoryDungeonFloor(),
        ),
    )
    .flat();
  const maxLowRecommendation = Math.max(
    ...floors.map((floor) => floor.getMinimumMPLRecommendation() ?? 0),
  );
  return maxLowRecommendation;
}

export function mplIsTooLow(state: GameState): boolean {
  const maxLowRecommendation = minMPLRecommendation(state);
  const currentMPL = getMaxOfMaxPrimaryElementLevels(state);
  return currentMPL < maxLowRecommendation;
}

export function maxMPLRecommendation(state: GameState): number {
  const unlockedDungeons = getUnlockedDungeons(state);
  const floors = unlockedDungeons
    .map((dungeon) =>
      dungeon
        .getDungeonFloors()
        .filter(
          (floor) => floor.isUnlocked(state) && floor.isMainStoryDungeonFloor(),
        ),
    )
    .flat();
  const maxHighRecommendation = Math.max(
    ...floors.map((floor) => floor.getMaximumMPLRecommendation() ?? Infinity),
  );
  return maxHighRecommendation;
}

export function mplIsTooHigh(state: GameState): boolean {
  const minHighRecommendation = maxMPLRecommendation(state);
  const currentMPL = getMaxOfMaxPrimaryElementLevels(state);
  return currentMPL > minHighRecommendation;
}

export function isStuckOnBoss(state: GameState): boolean {
  return (
    state.world.lastDungeonFloorCompleted ==
      state.run.lastDungeonFloorCompleted &&
    state.run.lastDungeonFloorCompleted != null &&
    state.run.endingTriggered == null &&
    state.run.currentChallengeId == null &&
    !hasFlag(state, Flag.CreatorPath)
  );
}

export function registerDungeonFloorEventOddsTransformation(
  event: GameEvent,
  baseFloorIdForMoreOdds: string,
) {
  registerTransformation(
    [[event.getId(), TransformationTags.RandomEventWeight]],
    event.getId() + "dungeonFloorMultiplier",
    t("Game progress"),
    TransformationType.Multiplier,
    (state) => {
      let dungeonFloor = DungeonFloors.getByIdNullable(baseFloorIdForMoreOdds);
      if (
        dungeonFloor == null ||
        !isDungeonFloorEverCompleted(state, dungeonFloor)
      ) {
        return 1.0;
      }

      let baseMultiplier = 2.0;
      while (dungeonFloor != null) {
        dungeonFloor = dungeonFloor.getNextFloor(state);
        if (dungeonFloor == null) {
          return baseMultiplier;
        }

        if (
          !isDungeonFloorEverCompleted(state, dungeonFloor) &&
          // Bottom behavior needed to account for Lost Forest variants
          (dungeonFloor.getNextFloor(state) == null ||
            !isDungeonFloorEverCompleted(
              state,
              dungeonFloor.getNextFloor(state),
            ))
        ) {
          return baseMultiplier;
        }

        // Then for every floor afterwards that is completed, add an extra multiplicative 10% to the chance
        // Example:
        // Storyline in the Training Towers will get a 2x boost after clearing Sewer Hideout,
        // 2.2x after Vast Desert, 2.42x after Pyramid, 2.66x after Burial Chambers,
        // 3.5x after Subterranean Sanctuary, etc.
        baseMultiplier *= 1.25;
      }
    },
  );
}

export function loadCommonDungeonLogic() {
  registerRetirementListener("dungeonLastFloorCompleted", (state, isMock) => {
    state.world.lastDungeonFloorCompleted = state.run.lastDungeonFloorCompleted;
    return state;
  });
}
