import { EventTriggerListeners } from "../events/Events";
import { LevelUpListeners } from "../events/progression/LevelUp";
import { addGameStateListener } from "../GameStateListeners";
import {
  registerPostRetirementListener,
  registerRetirementListener,
} from "../Retire";
import { storylineHintUnlockChecker, Storylines } from "./Storylines";

function loadStorylinesCore(): void {
  registerRetirementListener("StorylineBonusActivator", (state, isMock) => {
    Storylines.getAll().forEach((storyline) => {
      if (storyline.isCompleted(state) && !storyline.isBonusActive(state)) {
        state = storyline.activateBonus(state);
      }
    });
    return state;
  });

  EventTriggerListeners.register((state, event) => {
    for (let storyline of event.getStorylines()) {
      state = storyline.revealFullName(state);
    }
    return state;
  });

  LevelUpListeners.register(
    storylineHintUnlockChecker,
    "storylineHintUnlocker",
  );

  // Run the hint unlocker every minute
  addGameStateListener(
    "storylineHintUnlockerPeriodic",
    (state) => {
      return storylineHintUnlockChecker;
    },
    (state) => Math.floor(Date.now() / (1000 * 60)),
  );
  registerPostRetirementListener(
    "storylineHintUnlockerPostRetirement",
    (state, _isMock) => {
      return storylineHintUnlockChecker(state);
    },
  );
}

export { loadStorylinesCore };
