import React, { useCallback, useContext, useMemo, useState } from "react";
import {
  LayoutChangeEvent,
  Platform,
  ScrollView,
  StyleSheet,
  useWindowDimensions,
  View,
} from "react-native";
import { useTheme } from "react-native-paper";
import Animated, { CurvedTransition } from "react-native-reanimated";
import { ActionArea } from "../../backend/action/ActionAreas";
import { Flag } from "../../backend/Flag";
import { hasFlag } from "../../backend/Flags";
import { getFavoriteSpells } from "../../backend/spells/Spells";
import Styles from "../utility/Styles";
import { useGameState } from "../utility/useGameState";
import { VisibilityContext } from "../utility/VisibilityContext";
import { FavoriteSpellsContainer } from "./FavoriteSpellsContainer";
import SpellsContainer from "./SpellsContainer";

type Props = {
  favoritesOnBottom: boolean;
};

export function SpellMenuContents(props: { favoritesOnBottom: boolean }) {
  const theme = useTheme();
  const state = useGameState();
  const visible = useContext(VisibilityContext);
  const isBottomMenuEnabled = state.options.enableBottomMenu;
  const { height, width } = useWindowDimensions();
  const [favoritesHeight, setFavoritesHeight] = useState(null);

  const heightWithoutBottomMenu =
    height - (isBottomMenuEnabled && width < 640 ? 48 : 0);
  const hasFavorites =
    getFavoriteSpells(state).length > 0 ||
    (hasFlag(state, Flag.ChannelingUnlocked) &&
      !state.options.hideQuickChanneling);

  const onLayout = useCallback((event: LayoutChangeEvent) => {
    setFavoritesHeight(event.nativeEvent.layout.height);
  }, []);

  return useMemo(
    () => (
      <View style={{ flex: 1, backgroundColor: theme.colors.background }}>
        <ScrollView
          style={{ flex: 1 }}
          contentContainerStyle={styles.magicContainer}
          nativeID="spellMenuContainer"
        >
          <SpellsContainer
            uiKey="SpellMenuContainer"
            area={ActionArea.SPELL_MENU}
            onlyBySchool={props.favoritesOnBottom}
            showWizards={true}
            isVisible={visible}
          />
        </ScrollView>
        {props.favoritesOnBottom && hasFavorites && (
          <Animated.View
            layout={CurvedTransition.duration(100)}
            style={{
              height: Math.max(
                Math.min(
                  heightWithoutBottomMenu - 472,
                  favoritesHeight != null
                    ? Math.min(favoritesHeight + 16, 270)
                    : 270,
                ),
                40,
              ),
              borderTopColor: theme.colors.outlineVariant,
              borderTopWidth: 1,
            }}
          >
            {Platform.select({
              default: (
                <View style={[styles.favoritesContainer, Styles.flex]}>
                  <FavoriteSpellsContainer onLayout={onLayout} />
                </View>
              ),
              web: (
                <ScrollView contentContainerStyle={styles.favoritesContainer}>
                  <FavoriteSpellsContainer onLayout={onLayout} />
                </ScrollView>
              ),
            })}
          </Animated.View>
        )}
      </View>
    ),
    [
      theme,
      hasFavorites,
      props.favoritesOnBottom,
      heightWithoutBottomMenu,
      visible,
      favoritesHeight,
      onLayout,
    ],
  );
}

export function SpellMenu(props: Props) {
  return useMemo(() => {
    return <SpellMenuContents favoritesOnBottom={props.favoritesOnBottom} />;
  }, [props.favoritesOnBottom]);
}

const styles = StyleSheet.create({
  backdrop: {
    position: "absolute",
    height: "100%",
    width: "100%",
    backgroundColor: "#000",
    zIndex: 80,
  },
  backdropTouchable: {
    position: "absolute",
    height: "100%",
    width: "100%",
    zIndex: 90,
  },
  container: {
    justifyContent: "flex-start",
    alignItems: "stretch",
    position: "absolute",
    zIndex: 100,
    height: "100%",
    width: 300,
    right: 0,
    top: 0,
  },
  magicContainer: {
    padding: 8,
  },
  favoritesContainer: {
    paddingHorizontal: 8,
    paddingBottom: 8,
  },
});
